contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        c.fallback{value: amount}();

        uint256 balBefore = address(c).balance;
        bool reverted;
        if (caller == c.owner()) {
            try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
            assert(!reverted && address(c).balance == 0 && address(recipient).balance >= balBefore);
        } else {
            try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
            assert(reverted && address(c).balance == balBefore);
        }
    }

    receive() external payable {}
}

