    function run(uint256 amount, address recipient) public payable {
        require(recipient != address(0), "bad recipient");
        require(address(this).balance >= amount, "insufficient balance for funding");
        require(amount > 0, "amount must be positive");

        uint256 testBalBefore = address(this).balance;
        uint256 cBalBefore = address(c).balance;

        payable(address(c)).transfer(amount);

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalAfter = address(c).balance;
        uint256 testBalAfter = address(this).balance;

        assert(reverted && cBalAfter == cBalBefore && testBalAfter == testBalBefore);
    }

